class Solution {
public:
    int numberOfSubmatrices(vector<vector<char>>& grid) {
        int m = grid.size();
        int n = grid[0].size();

        vector<int> sum(n, 0);
        vector<int> xCount(n, 0);

        int result = 0;

        for (int i = 0; i < m; i++) {
            int rowPrefix = 0;
            int rowXPrefix = 0;
            for (int j = 0; j < n; j++) {
                int val = (grid[i][j] == 'X') ? 1 : (grid[i][j] == 'Y') ? -1 : 0;
                int xVal = (grid[i][j] == 'X') ? 1 : 0;

                rowPrefix += val;
                rowXPrefix += xVal;

                int curSum = sum[j] + rowPrefix;
                int curX = xCount[j] + rowXPrefix;

                if (curSum == 0 && curX >= 1) {
                    result++;
                }

                sum[j] = curSum;
                xCount[j] = curX;
            }
        }

        return result;
    }
};
